import{HostDocument}from'./host-document';
import{encodeSelectionRaster}from'../../../../src/shared/patent/design-selection-raster';
export async function verifyRetouch(){
 const big=document.createElement('canvas');big.width=big.height=4100;const bc=big.getContext('2d')!;bc.fillStyle='white';bc.fillRect(0,0,4100,4100);bc.fillStyle='black';bc.fillRect(0,0,32,32);const bd=new HostDocument({projectId:'retouch-big',width:4100,height:4100,layers:[{name:'Big',opacity:1,isVisible:true,hasClipping:false,mixModeStr:'source-over',image:big}]});try{bd.beginRetouch([100,100,1],{tool:'clone',size:10,hardness:1,opacity:1,strength:1,offset:{x:-90,y:-90},merged:false});bd.endRetouch();bd.undo();if(bd.canvas.getLayer(0).context.getImageData(100,100,1,1).data[0]!==255)throw Error('Large local retouch lost undo');bd.redo();if(bd.canvas.getLayer(0).context.getImageData(100,100,1,1).data[0]!==0)throw Error('Large redo failed');}finally{bd.destroy();big.width=big.height=0;}
 const transparent=document.createElement('canvas');transparent.width=32;transparent.height=16;const tx=transparent.getContext('2d')!;tx.fillStyle='rgba(255,0,0,0.5)';tx.fillRect(0,0,12,16);tx.fillStyle='rgba(0,0,255,0.5)';tx.fillRect(8,0,4,16);const td=new HostDocument({projectId:'retouch-alpha',width:32,height:16,layers:[{name:'Alpha',opacity:1,isVisible:true,hasClipping:false,mixModeStr:'source-over',image:transparent}]});
 try{const o={tool:'clone' as const,size:8,hardness:1,opacity:1,strength:1,offset:{x:-16,y:0},merged:false};const before=td.contentIdentity();td.beginRetouch([22,8,1],o);td.endRetouch();const alpha=td.canvas.getLayer(0).context.getImageData(22,8,1,1).data[3]!;if(alpha<127||alpha>128)throw Error('Source alpha lost');td.undo();const id=td.canvas.getLayer(0).id;td.setLayerLocks(id,{alpha:true});let noChange=false;try{td.beginRetouch([22,8,1],o);td.endRetouch();}catch{noChange=true;}if(!noChange||td.canvas.getLayer(0).context.getImageData(22,8,1,1).data[3]!==0)throw Error('Alpha lock ignored');td.setLayerLocks(id,{alpha:false});const push=td.history.push.bind(td.history);td.history.push=()=>{throw Error('admission rejected');};try{td.beginRetouch([22,8,1],o);td.endRetouch();}catch{}finally{td.history.push=push;}if(td.canvas.getLayer(0).context.getImageData(22,8,1,1).data[3]!==0)throw Error('Failed commit leaked preview');const target=td.newLayer('Retouch');td.beginRetouch([22,8,1],{...o,merged:true});td.endRetouch();if(td.canvas.getLayer(td.canvas.getLayers().findIndex(l=>l.id===target)).context.getImageData(22,8,1,1).data[3]!<127)throw Error('All visible layer sampling failed');td.undo();td.setActiveLayer(id);td.beginRetouch([11,8,1],{...o,tool:'blur',size:10});td.endRetouch();if(td.canvas.getLayer(0).context.getImageData(13,8,1,1).data[3]!==0)throw Error('Blur created opacity in transparent pixels');}finally{td.destroy();transparent.width=0;}
 const c=document.createElement('canvas');c.width=64;c.height=48;const x=c.getContext('2d')!;x.fillStyle='white';x.fillRect(0,0,64,48);x.fillStyle='black';x.fillRect(0,0,20,48);const d=new HostDocument({projectId:'retouch',width:64,height:48,layers:[{name:'Base',opacity:1,isVisible:true,hasClipping:false,mixModeStr:'source-over',image:c}]});
 const check=(v:unknown,m:string)=>{if(!v)throw Error(m);},pixel=(a:number,b:number)=>d.canvas.getLayer(0).context.getImageData(a,b,1,1).data;
 const o={tool:'clone' as const,size:10,hardness:1,opacity:1,strength:1,offset:{x:-30,y:0},merged:false};
 const fd=new HostDocument({projectId:'retouch-feather',width:64,height:48,layers:[{name:'Feather',opacity:1,isVisible:true,hasClipping:false,mixModeStr:'source-over',image:c}]});try{fd.select([[[[0,0],[64,0],[64,48],[0,48],[0,0]]]],'replace',{coverage:encodeSelectionRaster(64,48,new Uint8Array(64*48).fill(128))});fd.beginRetouch([40,20,1],o);for(let i=0;i<10;i++)fd.moveRetouch([40,20,1]);fd.endRetouch();const value=fd.canvas.getLayer(0).context.getImageData(40,20,1,1).data[0]!;if(value<126||value>128)throw Error('Repeated clone dabs defeated selection coverage');}finally{fd.destroy();}
 const flowDoc=new HostDocument({projectId:'retouch-flow',width:64,height:48,layers:[{name:'Flow',opacity:1,isVisible:true,hasClipping:false,mixModeStr:'source-over',image:c}]});try{flowDoc.beginRetouch([40,20,1],{...o,flow:0.5});flowDoc.endRetouch();const value=flowDoc.canvas.getLayer(0).context.getImageData(40,20,1,1).data[0]!;if(value<126||value>128)throw Error('Flow ignored');flowDoc.undo();flowDoc.beginRetouch([40,20,1],{...o,opacity:0.5});for(let i=0;i<10;i++)flowDoc.moveRetouch([40,20,1]);flowDoc.endRetouch();const cap=flowDoc.canvas.getLayer(0).context.getImageData(40,20,1,1).data[0]!;if(cap<126||cap>128)throw Error('Stroke opacity cap exceeded');}finally{flowDoc.destroy();}
 try{const before=d.contentIdentity(),count=d.capture().history.totalActions;d.beginRetouch([40,20,1],o);d.endRetouch();check(pixel(40,20)[0]===0,'Clone failed');check(d.capture().history.totalActions===count+1,'Not single undo');d.undo();check(before===d.contentIdentity(),'Undo failed');d.redo();const restored=await HostDocument.openProject(await d.exportProject());check(restored.canvas.getLayer(0).context.getImageData(40,20,1,1).data[0]===0,'Reopen failed');restored.destroy();d.undo();d.beginRetouch([40,20,1],o);d.cancelRetouch();check(d.contentIdentity()===before&&pixel(40,20)[0]===255,'Cancel failed');d.beginRetouch([20,20,1],{...o,tool:'blur',size:16});d.endRetouch();check(pixel(20,20)[0]!>0&&pixel(20,20)[0]!<255,'Blur failed');d.undo();d.select([[[[35,15],[40,15],[40,25],[35,25],[35,15]]]],'replace');d.beginRetouch([40,20,1],{...o,size:20});d.endRetouch();check(pixel(37,20)[0]===0&&pixel(42,20)[0]===255,'Selection ignored');d.undo();d.select(undefined,'replace');const id=d.canvas.getLayer(0).id;d.setLayerLocks(id,{pixels:true});let rejected=false;try{d.beginRetouch([40,20,1],o);}catch{rejected=true;}check(rejected,'Lock ignored');}finally{d.destroy();c.width=0;}
}
